(()=>{
'use strict';
const V='20261018-worlds-pilot-v1';
const model=window.CFF_TEAM_PROFILE_MODEL;
const ORG_PLAYER_STATS=`team-data/player-team-career.json?v=${V}`;
const root=document.getElementById('team-page-root');
const state={team:null,slug:'',current:null,stats:null,stages:null,seasonData:null,historyData:null,orgStats:null,activeSeason:'s2',historyExpanded:false,titlesExpanded:false,titleYear:'all',historyPromise:null,periodData:null,periodPromise:null,identity:null};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'');
const num=v=>Number(v)||0;
const format=v=>num(v).toLocaleString('pt-BR');
const decimal=(v,d=2)=>num(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const slug=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
const aliases={loud:'loud-snickers',fluxo:'fluxo-w7m',afg:'afrogames',a7:'alpha7',sxgaming:'sx-tet',sxtet:'sx-tet',cptvox:'cpt-vox',influencerage:'influence-rage',rise:'rise-gaming',rush:'rush-gaming',solid:'team-solid'};
function setCanonicalTeamRoute(team){const canonical=aliases[norm(team?.name)]||slug(team?.name),path=`/equipe/${canonical}`;if(!canonical)return;try{if(location.pathname!==path||location.search||location.hash)history.replaceState(history.state,'',path+(/^#cff-profile-(summary|roster|results|titles|history)$/.test(location.hash)?location.hash:''));let link=document.querySelector('link[rel=\"canonical\"]');if(!link){link=document.createElement('link');link.rel='canonical';document.head.appendChild(link)}link.href=location.origin+path;window.dispatchEvent(new CustomEvent('cff:pretty-route',{detail:{path,type:'team',slug:canonical}}))}catch(_){}}
async function json(url){const response=await fetch(url,{cache:'default'});if(!response.ok)throw new Error('Falha ao carregar os dados');return response.json()}
function findTeam(teams,query){const key=norm(query),mapped=aliases[key];return teams.find(t=>norm(t.name)===key||norm(t.abbreviation)===key||slug(t.name)===query||slug(t.name)===mapped)||teams.find(t=>slug(t.name)===mapped)||null}
function role(p){const value=String(p?.currentRoster?.roleShort||p?.currentRoster?.role||p?.role||'').toUpperCase();return value==='GRAN'?'Granadeiro':value==='SUP'?'Suporte':value==='3'?'3º homem':value==='RUSH'?'Rush':value||'Jogador'}
function photo(p){const base=window.cffResolvePlayerPhoto?.(p?.name,p?.photo)||p?.photo||'silhueta.webp';return /coach|analyst|analista|manager|tecnico|staff/i.test(String(p?.cargo||p?.role||''))?(window.cffCoachPhoto?.(p.name,base)||base):base}function teamLogo(name,current=''){return window.cffResolveTeamLogo?.(name,current)||current||'escudo.webp'}
function playerStats(p,stats){const candidates=[p.id,p.name,...(p.aliases||[])].map(norm);const hit=Object.entries(stats||{}).find(([key,value])=>candidates.includes(norm(key))||candidates.includes(norm(value?.name)));return hit?.[1]||p.s2||{}}
function s2Outcome(stages,name){const final=stages?.final||{},champion=String(final.champion||final.confirmedChampion||'').trim(),row=(final.rows||[]).find(item=>norm(item.team||item.equipe||item.name)===norm(name));if(!champion)return{subtitle:'Desempenho na WB 2026 S2',result:''};if(norm(champion)===norm(name))return{subtitle:'Campeã da WB 2026 S2',result:'Campeã'};if(row?.position&&num(row.matches)>0)return{subtitle:`${format(row.position)}º lugar na Final • Champion Rush`,result:`${format(row.position)}º`};return{subtitle:row?'Finalista da WB 2026 S2':'Campanha encerrada na Classificatória',result:row?'Finalista':'Classificatória'}}

function isDeparted(p){const r=p?.currentRoster||{};return Boolean(r.left)||norm(r.rosterStatus)==='saiu'}function tags(p){const roster=p.currentRoster||{};if(isDeparted(p))return'<span class="cff-player-tag departed">Saiu</span>';return[(roster.captain?'<span class="cff-player-tag captain">Capitão</span>':''),(roster.rookie?'<span class="cff-player-tag rookie">Estreante</span>':''),(roster.highlight?'<span class="cff-player-tag">Destaque</span>':''),(!roster.starter?'<span class="cff-player-tag">Reserva</span>':'')].join('')}
function currentPlayerCard(p,stats,logo){
 const s=playerStats(p,stats),roster=p.currentRoster||{},avg=num(s.matches)?num(s.kills)/num(s.matches):null;
 const total=s2TeamRows().reduce((a,row)=>a+num(row.kills),0),share=total?num(s.kills)/total*100:null;
 return `<a class="cff-player-card${isDeparted(p)?' is-departed':(roster.starter===false?' is-reserve':'')}" href="jogador.html?id=${encodeURIComponent(p.id||p.name)}"><div class="cff-player-photo-wrap"><img class="cff-player-photo" data-player-photo="${esc(p.name)}" loading="lazy" decoding="async" src="${esc(photo(p))}" alt="${esc(p.name)}" onerror="this.onerror=null;this.src='silhueta.webp'"><img class="cff-player-team-mini" src="${esc(logo)}" data-team-logo="${esc(state.team?.name||'')}" alt=""></div><div class="cff-player-info"><h3>${esc(p.name)}</h3><span class="cff-player-role">${esc(role(p))} • ${esc(roster.rosterStatus||'Elenco')}</span><span class="cff-player-realname">${esc(roster.fullName||'')}${roster.state?` • ${esc(roster.state)}`:''}</span><div class="cff-player-tags">${tags(p)}</div></div><div class="cff-player-stats"><div class="cff-player-stat"><small>Abates</small><strong>${format(s.kills)}</strong></div><div class="cff-player-stat"><small>Dano</small><strong>${format(s.damage)}</strong></div><div class="cff-player-stat"><small>Quedas</small><strong>${format(s.matches)}</strong></div><div class="cff-player-stat"><small>Abates/queda</small><strong>${avg===null?'—':decimal(avg)}</strong></div></div><span class="cff-kill-share">${share===null?'Sem abates registrados':`${decimal(share,1)}% dos abates da equipe na WB 2026 S2`}</span></a>`;
}
function seasonPlayerCard(p,logo){return `<a class="cff-player-card" href="jogador.html?id=${encodeURIComponent(p.id||p.name)}"><div class="cff-player-photo-wrap"><img class="cff-player-photo" data-player-photo="${esc(p.name)}" loading="lazy" decoding="async" src="${esc(photo(p))}" alt="${esc(p.name)}" onerror="this.onerror=null;this.src='silhueta.webp'"><img class="cff-player-team-mini" src="${esc(logo)}" data-team-logo="${esc(state.team?.name||'')}" alt=""></div><div class="cff-player-info"><h3>${esc(p.name)}</h3><span class="cff-player-role">${esc(role(p))}</span></div><div class="cff-player-stats"><div class="cff-player-stat"><small>Abates</small><strong>${format(p.kills)}</strong></div><div class="cff-player-stat"><small>Dano</small><strong>${format(p.damage)}</strong></div><div class="cff-player-stat"><small>Quedas</small><strong>${format(p.matches)}</strong></div><div class="cff-player-stat"><small>Média</small><strong>${decimal(p.avg)}</strong></div></div></a>`}
function statCards(values){return `<section class="cff-team-stats">${values.map(([label,value])=>`<div class="cff-team-stat"><small>${esc(label)}</small><strong>${esc(value)}</strong></div>`).join('')}</section>`}
function stageCards(stages){if(!Array.isArray(stages)||!stages.length)return'';return `<div class="cff-season-stage-grid">${stages.map(stage=>`<article class="cff-season-stage-card${stage.champion?' is-champion':''}"><div class="cff-season-stage-top"><strong>${esc(stage.label||stage.id||'Etapa')}</strong><span>${stage.position?`${format(stage.position)}º`:'—'}</span></div><div class="cff-season-stage-stats"><span><b>${format(stage.points)}</b><small>Pontos</small></span><span><b>${format(stage.kills)}</b><small>Abates</small></span><span><b>${format(stage.booyahs)}</b><small>Booyahs</small></span><span><b>${format(stage.matches)}</b><small>Quedas</small></span></div>${stage.status?`<div class="cff-season-status">${esc(stage.status)}</div>`:''}</article>`).join('')}</div>`}
function seasonHeader(title,subtitle){return `<div class="cff-team-section-head cff-season-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div></div>`}
function renderS2(){
 state.activeSeason='s2';setSeasonButtons();
 const players=Object.values(state.current?.players||{}),campaign=model.campaign(state.stages,state.team.name),outcome=s2Outcome(state.stages,state.team.name);
 const latest=campaign.rounds.at(-1),totals=campaign.totals,logo=teamLogo(state.team.name,state.team.logo);
 document.getElementById('cff-season-panel').innerHTML=`${seasonHeader('WB 2026 S2',outcome.subtitle)}${statCards([...(outcome.result?[['Resultado',outcome.result]]:[]),['Pontos',format(totals.points+campaign.rounds.reduce((a,r)=>a+num(r.bonus),0))],['Abates',format(totals.kills)],['Booyahs',format(totals.booyahs)],['Quedas',format(totals.matches)]])}<p class="cff-data-note">Totais das etapas com resultados disponíveis${latest?` · Última etapa: ${esc(latest.label)}`:''}. Atualizado em ${esc(dateBR(state.stages?.updatedAt))}.</p>${performanceCards(campaign.rates,campaign.benchmark)}${stageCards(campaign.rounds)}<details class="cff-competition-roster"><summary>Ver elenco registrado na WB 2026 S2</summary><p class="cff-data-note">Jogadores da competição, incluindo quem já saiu. Abates e dano acumulados na WB 2026 S2.</p><div class="cff-team-roster">${players.map(p=>currentPlayerCard(p,state.stats?.players,logo)).join('')}</div></details>`;
}
async function ensureSeasonData(){if(state.seasonData)return state.seasonData;state.seasonData=await json(`team-data/seasons/${state.slug}.json?v=${V}`);return state.seasonData}
async function selectSeason(key){if(key==='s2'){renderS2();return}state.activeSeason=key;setSeasonButtons();const panel=document.getElementById('cff-season-panel');panel.innerHTML='<section class="cff-inline-loading"><span></span><strong>Carregando temporada...</strong></section>';try{const data=await ensureSeasonData();if(state.activeSeason!==key||document.querySelector(`[data-team-season="${key}"]`)?.getAttribute('aria-selected')!=='true')return;const season=data?.seasons?.[key];if(!season){panel.innerHTML=`${seasonHeader(key==='s1'?'WB 2026 S1':'EWC 2026','A equipe não disputou esta competição.')}<div class="cff-public-empty">Nenhum resultado registrado para esta equipe.</div>`;return}const stages=season.stages||[],last=stages[stages.length-1]||{},totals=stages.reduce((a,s)=>(a.points+=num(s.points),a.kills+=num(s.kills),a.booyahs+=num(s.booyahs),a.matches+=num(s.matches),a),{points:0,kills:0,booyahs:0,matches:0});const players=season.players||[],title=key==='s1'?'WB 2026 S1':'EWC 2026';panel.innerHTML=`${seasonHeader(title,last.status||'Desempenho da equipe')}${statCards([['Resultado final',last.position?`${format(last.position)}º`:'—'],['Pontos',format(totals.points)],['Abates',format(totals.kills)],['Quedas',format(totals.matches)]])}${performanceCards(model.rates(totals))}${stageCards(stages)}<section class="cff-team-section cff-season-roster-section"><div class="cff-team-section-head"><div><h2>Jogadores na competição</h2></div><span class="cff-team-badge">${players.length} jogadores</span></div><div class="cff-team-roster">${players.length?players.map(p=>seasonPlayerCard(p,teamLogo(state.team.name,state.team.logo))).join(''):'<div class="cff-public-empty">Elenco da competição não encontrado.</div>'}</div></section>`}catch(error){if(state.activeSeason===key&&document.querySelector(`[data-team-season="${key}"]`)?.getAttribute('aria-selected')==='true')panel.innerHTML='<div class="cff-public-empty">Não foi possível carregar os dados desta competição.</div>'}}
function setSeasonButtons(){document.querySelectorAll('[data-team-season]').forEach(button=>{const active=button.dataset.teamSeason===state.activeSeason;button.classList.toggle('is-active',active);button.setAttribute('aria-selected',active?'true':'false')})}
async function ensurePeriodData(){if(state.periodData)return Promise.resolve(state.periodData);if(!state.periodPromise)state.periodPromise=json('/team-data/competition-periods.json?v=20261018-periodos-coaches-v1').then(data=>state.periodData=data).catch(()=>null).finally(()=>state.periodPromise=null);return state.periodPromise;}
function teamPeriod(p,name){const data=state.periodData,key=data?.aliases?.[norm(name)]||norm(name),rows=data?.teams?.[key],spans=rows?.[norm(p.id)]||rows?.[norm(p.name)];if(!spans?.length)return'';return spans.map(([first,last],i)=>esc(first)+' > '+esc(p.isCurrent&&i===spans.length-1?'ATUAL':last)).join(' / ');}
function ensureHistoryData(){
 if(state.historyData)return state.historyData;
 if(!state.historyPromise)state.historyPromise=json(`team-data/history/${state.slug}.json?v=${V}`).then(data=>(state.historyData=data)).finally(()=>{state.historyPromise=null});
 return state.historyPromise;
}
async function ensureOrgStats(){if(state.orgStats)return state.orgStats;state.orgStats=await json(ORG_PLAYER_STATS).catch(()=>({teams:{}}));return state.orgStats}
function softPlayerKey(value){return norm(value).replace(/\d+$/,'')}
function s2TeamRows(){return Object.values(state.stats?.players||{}).filter(row=>norm(row?.team)===norm(state.team?.name))}
function findS2Stat(names){const keys=(names||[]).filter(Boolean).map(norm),hit=s2TeamRows().find(row=>keys.includes(norm(row?.name)));if(hit)return hit;const soft=keys.map(softPlayerKey).filter(Boolean),near=s2TeamRows().filter(row=>soft.includes(softPlayerKey(row?.name)));return near.length===1?near[0]:null}
function baseOrgRow(p){const team=state.orgStats?.teams?.[state.slug],rows=team?.players||[],keys=[p?.id,p?.name,...(p?.aliases||[])].filter(Boolean).map(norm);let hit=rows.find(row=>[row.name,...(row.aliases||[])].some(name=>keys.includes(norm(name))));if(hit)return hit;const softKeys=keys.map(softPlayerKey).filter(Boolean),near=rows.filter(row=>[row.name,...(row.aliases||[])].some(name=>softKeys.includes(softPlayerKey(name))));return near.length===1?near[0]:null}
function overlayOrgRow(base,s2){if(!base&&!s2)return null;const historicalKills=num(base?.historicalKills??Math.max(0,num(base?.kills)-num(base?.currentKills))),historicalMatches=num(base?.historicalMatches??Math.max(0,num(base?.matches)-num(base?.currentMatches)));const currentKills=s2?num(s2.kills):num(base?.currentKills),currentMatches=s2?num(s2.matches):num(base?.currentMatches);return{...(base||{}),name:base?.name||s2?.name||'',aliases:base?.aliases||[s2?.name].filter(Boolean),historicalKills,historicalMatches,currentKills,currentMatches,kills:historicalKills+currentKills,matches:historicalMatches+currentMatches}}
function organizationPlayerStat(p){const base=baseOrgRow(p),s2=findS2Stat([p?.id,p?.name,...(base?.aliases||[]),base?.name]);return overlayOrgRow(base,s2)}
function organizationRows(){const team=state.orgStats?.teams?.[state.slug],base=team?.players||[],map=new Map;base.forEach(row=>{const s2=findS2Stat([row.name,...(row.aliases||[])]),merged=overlayOrgRow(row,s2);if(merged)map.set(norm(merged.name),merged)});s2TeamRows().forEach(s2=>{const existing=[...map.values()].find(row=>[row.name,...(row.aliases||[])].some(name=>norm(name)===norm(s2.name)));if(existing){map.set(norm(existing.name),overlayOrgRow(existing,s2))}else map.set(norm(s2.name),overlayOrgRow(null,s2))});return[...map.values()].sort((a,b)=>num(b.kills)-num(a.kills)||num(b.matches)-num(a.matches)||String(a.name).localeCompare(String(b.name),'pt-BR'))}
function currentPlayerMeta(name){const players=Object.values(state.current?.players||{}),key=norm(name);return players.find(p=>norm(p?.name)===key||norm(p?.id)===key)||null}
function closeTeamWbRanking(){const modal=document.getElementById('cff-team-wb-ranking-modal');if(modal)modal.hidden=true;document.body.classList.remove('cff-modal-open')}
function openTeamWbRanking(){const modal=document.getElementById('cff-team-wb-ranking-modal'),body=document.getElementById('cff-team-wb-ranking-body');if(!modal||!body)return;const rows=organizationRows();body.innerHTML=rows.map((r,i)=>{const meta=currentPlayerMeta(r.name),id=r.id||meta?.id||meta?.name,name=id?`<a href="jogador.html?id=${encodeURIComponent(id)}">${esc(r.name)}</a>`:esc(r.name);return`<tr><td>${i+1}</td><td style="text-align:left">${name}</td><td><strong>${format(r.kills)}</strong></td><td>${format(r.matches)}</td></tr>`}).join('')||'<tr><td colspan="4">Nenhum histórico de abates encontrado para esta equipe.</td></tr>';modal.hidden=false;document.body.classList.add('cff-modal-open')}
function historyCard(p){const editions=teamPeriod(p,state.team?.name)||(p.editions||[]).slice(-3).join(' • '),tag=p.isCurrent?'ELENCO ATUAL':String(p.cargo||'').toUpperCase()==='COACH'?'EX-TREINADOR':'EX-JOGADOR',org=organizationPlayerStat(p),orgKills=org?`${format(org.kills)} K`:(p.hasProfile===false?'—':'VER'),content=`<img src="${esc(photo(p))}" data-player-photo="${esc(p.name)}" alt="${esc(p.name)}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='silhueta.webp'"><span><strong>${esc(p.name)}</strong><small>${tag}</small><em>${esc(editions||p.currentTeam||'Passagem registrada')}</em></span><b title="Abates feitos por esta organização, com a WB 2026 S2 atualizada">${orgKills}</b>`;return p.hasProfile===false?`<article class="cff-history-player${p.isCurrent?' is-current':''} is-static">${content}</article>`:`<a class="cff-history-player${p.isCurrent?' is-current':''}" href="jogador.html?id=${encodeURIComponent(p.id||p.name)}">${content}</a>`}
function renderHistory(data){const mount=document.getElementById('cff-team-history-mount'),players=data?.history?.players||[],limit=state.historyExpanded?players.length:12,shown=players.slice(0,limit),leader=organizationRows()[0];mount.innerHTML=`<div class="cff-team-section-head"><div><h2>Jogadores que já defenderam a equipe</h2></div><div class="cff-history-counts">${leader?`<span>Maior artilheiro: ${esc(leader.name)} · ${format(leader.kills)} K</span>`:''}<button type="button" class="cff-history-rank-btn" id="cff-team-wb-ranking-btn">Ranking histórico de abates</button><span>${format(data?.history?.currentCount)} atuais</span><span>${format(data?.history?.formerCount)} ex-jogadores</span></div></div><div class="cff-history-grid">${shown.length?shown.map(historyCard).join(''):'<div class="cff-public-empty">Nenhum histórico de jogadores cadastrado.</div>'}</div>${data?.history?.staff?.length?`<details class="cff-competition-roster"><summary>Comissão nas competições registradas · ${data.history.staff.length}</summary><div class="cff-history-grid">${data.history.staff.map(p=>`<a class="cff-history-player" href="/carreira.html?id=${encodeURIComponent(p.id)}"><img src="${esc(photo(p))}" alt="" loading="lazy"><span><strong>${esc(p.name)}</strong><small>${esc(({coach:'Coach',head_coach:'Head coach',analyst:'Analista',assistant_coach:'Auxiliar técnico',manager:'Manager',other:'Comissão'})[p.cargo]||p.cargo)}</small><em>${teamPeriod(p,state.team?.name)||esc(p.editions?.join(' · '))}</em></span></a>`).join('')}</div></details>`:''}${players.length>12?`<button type="button" class="cff-section-more" id="cff-history-toggle">${state.historyExpanded?'Mostrar menos':'Ver todos os jogadores'}</button>`:''}`;document.getElementById('cff-history-toggle')?.addEventListener('click',()=>{state.historyExpanded=!state.historyExpanded;renderHistory(data)});document.getElementById('cff-team-wb-ranking-btn')?.addEventListener('click',openTeamWbRanking)}
function titleCard(t){
 const content=`<img src="${esc(window.cffResolveTournamentLogo?.(t.event,t.logo||'trofeu.webp')||t.logo||'trofeu.webp')}" alt="" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='trofeu.webp'"><div><strong>${esc(t.type||'Campeão')}</strong><span>${esc(t.event||'Competição')}</span><small>${esc(dateBR(t.date))}${t.tier?` · ${esc(t.tier)}`:''}</small>${safeLink(t.url)?'<em>Ver campeonato ↗</em>':''}</div>`;
 return safeLink(t.url)?`<a class="cff-title-card${t.featured?' is-featured':''}" href="${esc(t.url)}">${content}</a>`:`<article class="cff-title-card${t.featured?' is-featured':''}">${content}</article>`;
}
function renderTitles(data){
 const mount=document.getElementById('cff-team-titles-mount'),all=model.titles(data?.titles),years=[...new Set(all.map(model.year))].sort().reverse(),filtered=state.titleYear==='all'?all:all.filter(t=>model.year(t)===state.titleYear),shown=state.titlesExpanded?filtered:filtered.slice(0,8);
 mount.innerHTML=`<div class="cff-team-section-head"><div><h2>Títulos coletivos</h2><p>Principais conquistas primeiro, com filtro por ano.</p></div><span class="cff-team-badge">${all.length} conquistas</span></div><label class="cff-title-filter">Ano <select id="cff-title-year"><option value="all">Todos os anos</option>${years.map(year=>`<option value="${esc(year)}"${state.titleYear===year?' selected':''}>${esc(year)}</option>`).join('')}</select></label><div class="cff-title-grid">${shown.length?shown.map(titleCard).join(''):'<div class="cff-public-empty">Nenhum título coletivo cadastrado neste período.</div>'}</div>${filtered.length>8?`<button type="button" class="cff-section-more" id="cff-titles-toggle">${state.titlesExpanded?'Mostrar menos':`Ver todas as ${filtered.length} conquistas`}</button>`:''}`;
 document.getElementById('cff-titles-toggle')?.addEventListener('click',()=>{state.titlesExpanded=!state.titlesExpanded;renderTitles(data)});
 document.getElementById('cff-title-year')?.addEventListener('change',event=>{state.titleYear=event.target.value;state.titlesExpanded=false;renderTitles(data)});
 renderHighlights(all);
}
function placeBR(value){return String(value||'—').replace(/1st/i,'1º').replace(/2nd/i,'2º').replace(/3rd/i,'3º').replace(/(\d+)th/i,'$1º')}
function renderResults(data){
 const mount=document.getElementById('cff-team-results-mount'),rows=[...(data?.results||[])].sort((a,b)=>String(b.data||'').localeCompare(String(a.data||''))).slice(0,8);
 mount.innerHTML=`<div class="cff-team-section-head"><div><h2>Resultados recentes</h2><p>Últimas participações registradas.</p></div></div><div class="cff-results-list">${rows.length?rows.map(r=>{const content=`<strong>${esc(r.torneio||'Competição')}</strong><span>${esc(dateBR(r.data))}</span><b>${esc(placeBR(r.place))}</b><small>${esc(r.tier||'')}</small>`;return safeLink(r.url)?`<a class="cff-result-row" href="${esc(r.url)}">${content}</a>`:`<article class="cff-result-row">${content}</article>`}).join(''):'<div class="cff-public-empty">Nenhum resultado recente cadastrado.</div>'}</div>`;
}
async function loadHistorySections(){
 const section=document.getElementById('cff-team-history-section');if(!section||section.dataset.loaded==='1')return;section.dataset.loaded='1';
 try{const [data]=await Promise.all([ensureHistoryData(),ensurePeriodData()]);renderHistory(data);await ensureOrgStats();renderHistory(data)}catch(error){section.dataset.loaded='';document.getElementById('cff-team-history-mount').innerHTML='<div class="cff-public-empty">Histórico indisponível no momento. <button type="button" id="cff-history-retry">Tentar novamente</button></div>';document.getElementById('cff-history-retry')?.addEventListener('click',loadHistorySections)}
}
function observeHistory(){const section=document.getElementById('cff-team-history-section');if(!section)return;if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){observer.disconnect();loadHistorySections()}},{rootMargin:'500px 0px'});observer.observe(section)}else setTimeout(loadHistorySections,500)}
function renderShell(team){
 const logo=teamLogo(team.name,team.logo);document.title=`${team.name} | Central Free Fire`;
 root.innerHTML=`<section class="cff-team-hero"><img class="cff-team-logo" fetchpriority="high" width="138" height="138" src="${esc(logo)}" data-team-logo="${esc(team.name)}" alt="${esc(team.name)}"><div><span class="cff-team-kicker">EQUIPE DE FREE FIRE</span><h1>${esc(team.name)}</h1><p>${esc(team.abbreviation||team.name)} • Brasil</p><div id="cff-team-socials" class="cff-team-socials"></div></div><span class="cff-team-country">Brasil</span></section><div id="cff-team-highlights"></div><nav class="cff-profile-nav" aria-label="Seções do perfil">${[['summary','Resumo'],['roster','Elenco'],['results','Resultados'],['titles','Títulos'],['history','História']].map(([id,label],i)=>`<a href="${esc(profileSectionHref(id))}" data-profile-section="${id}"${i===0?' aria-current="location"':''}>${label}</a>`).join('')}</nav><section id="cff-profile-summary" class="cff-profile-section" tabindex="-1"><nav class="cff-season-tabs" aria-label="Competições"><button type="button" data-team-season="s2" class="is-active" aria-selected="true">WB 2026 S2</button><button type="button" data-team-season="s1" aria-selected="false">WB 2026 S1</button><button type="button" data-team-season="ewc" aria-selected="false">EWC 2026</button></nav><div id="cff-season-panel"><section class="cff-inline-loading"><span></span><strong>Carregando desempenho...</strong></section></div></section><section id="cff-profile-roster" class="cff-profile-section cff-team-section" tabindex="-1"><div id="cff-current-roster"><section class="cff-inline-loading"><span></span><strong>Carregando elenco...</strong></section></div></section><section id="cff-profile-results" class="cff-profile-section cff-team-section" tabindex="-1"><div id="cff-team-results-mount"></div></section><section id="cff-profile-titles" class="cff-profile-section cff-team-section" tabindex="-1"><div id="cff-team-titles-mount"></div></section><section id="cff-profile-history" class="cff-profile-section cff-team-section" tabindex="-1"><div id="cff-team-history-section" class="cff-history-section"><div id="cff-team-history-mount"><section class="cff-inline-loading"><span></span><strong>Carregando histórico...</strong></section></div></div></section><div class="cff-team-ranking-modal" id="cff-team-wb-ranking-modal" hidden><div class="cff-team-ranking-dialog" role="dialog" aria-modal="true" aria-labelledby="cff-team-wb-ranking-title"><div class="cff-team-ranking-head"><div><small>HISTÓRICO DA ORGANIZAÇÃO</small><h2 id="cff-team-wb-ranking-title">Ranking de abates da equipe</h2></div><button type="button" id="cff-team-wb-ranking-close" aria-label="Fechar">×</button></div><div class="cff-team-ranking-table-wrap"><table class="cff-team-ranking-table"><thead><tr><th>#</th><th style="text-align:left">Jogador</th><th>K</th><th>Q</th></tr></thead><tbody id="cff-team-wb-ranking-body"></tbody></table></div></div></div>`;
 document.getElementById('cff-team-wb-ranking-close')?.addEventListener('click',closeTeamWbRanking);
 document.getElementById('cff-team-wb-ranking-modal')?.addEventListener('click',event=>{if(event.target.id==='cff-team-wb-ranking-modal')closeTeamWbRanking()});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.getElementById('cff-team-wb-ranking-modal')?.hidden)closeTeamWbRanking()});
 document.querySelectorAll('[data-team-season]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.teamSeason!=='s2'||state.current)selectSeason(button.dataset.teamSeason)}));
 setupSectionNavigation();observeHistory();
}

function dateBR(value){const text=String(value||'');return /^\d{4}-\d{2}-\d{2}$/.test(text)?text.split('-').reverse().join('/'):text||'Data não informada'}
function safeLink(value){return /^(https:\/\/|\/(?:ffws-|ewc|laff)[a-z0-9/_-]+(?:$|[?])|(?:ffws-|ewc|laff)[a-z0-9 /_-]*[.]html)/i.test(String(value||''))&&!/[<>"']/.test(value)}
function performanceCards(values,benchmark){
 const list=[['points','Pontos por queda',''],['kills','Abates por queda',''],['booyahs','Quedas com Booyah','%']];
 return `<div class="cff-performance-grid">${list.map(([key,label,suffix])=>{const value=values[key],base=benchmark?.[key],diff=value!==null&&base!==undefined&&base!==null?value-base:null;return `<article class="cff-performance-card"><small>${label}</small><strong>${value===null?'—':decimal(value,key==='booyahs'?1:2)+suffix}</strong>${diff===null?'':`<span class="${diff>=0?'is-above':'is-below'}">${diff>=0?'+':''}${decimal(diff,key==='booyahs'?1:2)}${key==='booyahs'?' p.p.':''} em relação à média</span><em>Média do torneio: ${decimal(base,key==='booyahs'?1:2)}${suffix}</em>`}</article>`}).join('')}</div><p class="cff-data-note">Médias calculadas nas etapas acima; pontos por queda excluem bônus de classificação.${benchmark?' Comparação com todas as equipes nas mesmas etapas.':''}</p>`;
}
function renderCurrentRoster(){
 const players=Object.values(state.current?.players||{}).filter(p=>!isDeparted(p)).sort((a,b)=>Number(b.currentRoster?.starter)-Number(a.currentRoster?.starter)||Number(b.currentRoster?.captain)-Number(a.currentRoster?.captain)||String(a.name).localeCompare(String(b.name),'pt-BR'));
 const departed=Object.values(state.current?.players||{}).filter(isDeparted),changes=Object.values(state.current?.players||{}).filter(p=>p.currentRoster?.joinedAt||p.currentRoster?.leftAt);
 document.getElementById('cff-current-roster').innerHTML=`<div class="cff-team-section-head"><div><h2>Elenco atual</h2><p>Elenco cadastrado · atualizado em ${esc(dateBR(state.current?.updatedAt))}. Estatísticas da WB 2026 S2.</p></div><span class="cff-team-badge">${players.filter(p=>p.currentRoster?.starter!==false).length} titulares · ${players.filter(p=>p.currentRoster?.starter===false).length} reservas</span></div><div class="cff-team-roster">${players.map(p=>currentPlayerCard(p,state.stats?.players,teamLogo(state.team.name,state.team.logo))).join('')}</div>${changes.length?`<div class="cff-roster-changes"><h3>Movimentações registradas</h3>${changes.map(p=>`<p><strong>${esc(p.name)}</strong> · ${p.currentRoster.leftAt?'Saída':'Entrada'} em ${esc(dateBR(p.currentRoster.leftAt||p.currentRoster.joinedAt))}</p>`).join('')}</div>`:''}${departed.length?`<p class="cff-data-note">Saídas registradas nesta temporada: ${departed.map(p=>esc(p.name)).join(', ')}. O elenco da competição está disponível na aba Resumo.</p>`:''}`;
 const mount=document.getElementById('cff-current-roster');if(mount){mount.insertAdjacentHTML('beforeend','<section id="cff-current-staff" class="cff-team-coaches" aria-label="Comissão técnica"></section>');renderCurrentStaff();}
}
async function renderCurrentStaff(){
 const mount=document.getElementById('cff-current-staff');if(!mount)return;
 try{const file=await json('/player-data/staff/wb-2026-s2-public.json?v=20261018-periodos-coaches-v1');if(!mount.isConnected)return;
 const people=(file.people||[]).filter(p=>norm(p.team)===norm(state.team?.name));
 const names={head_coach:'Head coach',coach:'Coach',assistant_coach:'Coach auxiliar',analyst:'Analista',manager:'Manager'};
 mount.innerHTML='<div class="cff-team-section-head"><div><h2>Comissão técnica</h2><p>Profissionais inscritos na WB 2026 S2, incluindo analistas.</p></div><span class="cff-team-badge">'+people.length+' integrantes</span></div>'+(people.length?'<div class="cff-history-grid">'+people.map(p=>{const pic=window.cffCoachPhoto?.(p.name,'silhueta.webp')||'silhueta.webp',href=p.id?'/carreira.html?id='+encodeURIComponent(p.id):'/carreira.html?name='+encodeURIComponent(p.name);return '<a class="cff-history-player" href="'+esc(href)+'"><img src="'+esc(pic)+'" alt="'+esc(p.name)+'" width="58" height="64" loading="lazy" decoding="async" onerror="this.onerror=null;this.src=\'/silhueta.webp\'"><span><strong>'+esc(p.name.replace('(coach)','').trim())+'</strong><small>'+esc(names[p.role]||'Comissão')+'</small><em>WB 2026 S2</em></span></a>';}).join('')+'</div>':'<p class="cff-data-note">Nenhuma comissão registrada para esta equipe nesta edição.</p>');
 }catch{if(mount.isConnected)mount.innerHTML='<p class="cff-data-note">Comissão técnica temporariamente indisponível.</p>';}
}
function renderHighlights(titles){
 const mount=document.getElementById('cff-team-highlights'),featured=titles.slice(0,3);
 mount.innerHTML=featured.length?`<section class="cff-team-highlights" aria-label="Principais conquistas"><div class="cff-highlights-head"><strong>Principais conquistas</strong><a href="${esc(profileSectionHref('titles'))}" data-profile-jump="titles">Ver títulos ↓</a></div><div class="cff-title-grid">${featured.map(titleCard).join('')}</div></section>`:'';
}
function applyIdentity(){const accent=state.identity?.accent;if(/^#[a-f0-9]{6}$/i.test(accent)){root.style.setProperty('--accent',accent);root.style.setProperty('--team-accent-rgb',`${parseInt(accent.slice(1,3),16)},${parseInt(accent.slice(3,5),16)},${parseInt(accent.slice(5,7),16)}`)}const mount=document.getElementById('cff-team-socials');if(mount)mount.innerHTML=(state.identity?.socials||[]).filter(s=>safeLink(s.url)).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('')}
function refreshImages(){document.querySelectorAll('#team-page-root [data-player-photo]').forEach(img=>{const src=window.cffResolvePlayerPhoto?.(img.dataset.playerPhoto,img.getAttribute('src'));if(src&&src!==img.getAttribute('src')){img.onerror=function(){this.onerror=null;this.src='silhueta.webp'};img.src=src}});document.querySelectorAll('#team-page-root [data-team-logo]').forEach(img=>{const src=teamLogo(img.dataset.teamLogo,state.team.logo);if(src!==img.getAttribute('src'))img.src=src})}
function profileSectionHref(id){return `/equipe/${state.slug}#cff-profile-${id}`}
function jumpToProfileSection(id){
 const section=document.getElementById(`cff-profile-${id}`);if(!section)return;
 if(id==='history')loadHistorySections();
 section.focus({preventScroll:true});section.scrollIntoView({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
 history.replaceState(history.state,'',profileSectionHref(id));
 document.querySelectorAll('[data-profile-section]').forEach(link=>{if(link.dataset.profileSection===id)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')});
}
function setupSectionNavigation(){
 const measure=()=>{const h=document.querySelector('.cff-public-topbar')?.getBoundingClientRect().height||65;root.style.setProperty('--cff-profile-nav-top',`${h}px`);root.style.setProperty('--cff-profile-scroll-offset',`${h+70}px`)};measure();if('ResizeObserver'in window){const header=document.querySelector('.cff-public-topbar');if(header)new ResizeObserver(measure).observe(header)}else window.addEventListener('resize',measure);
 // Delegation also handles the highlights link, which is rendered asynchronously.
 root.addEventListener('click',event=>{const link=event.target.closest?.('[data-profile-section], [data-profile-jump]');if(!link||event.defaultPrevented||event.button>0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();jumpToProfileSection(link.dataset.profileSection||link.dataset.profileJump)});
 if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top)[0];if(!visible)return;const id=visible.target.id.replace('cff-profile-','');document.querySelectorAll('[data-profile-section]').forEach(link=>{if(link.dataset.profileSection===id)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')})},{rootMargin:'-130px 0px -55% 0px',threshold:0});document.querySelectorAll('.cff-profile-section').forEach(section=>observer.observe(section))}
}

function fail(message){root.innerHTML=`<section class="cff-team-error"><div><h1>Equipe não encontrada</h1><p>${esc(message||'Não foi possível carregar este perfil.')}</p><a href="index.html#ffws-br-s2-equipes">Voltar para as equipes</a></div></section>`}
async function init(){
 try{
  const params=new URLSearchParams(location.search),query=params.get('time')||params.get('id')||'';
  const teamsData=await json(`ffws-br-2026-s2/teams.json?v=${V}`),team=findTeam(teamsData.teams||[],query);if(!team)throw new Error('O nome informado não pertence aos times da temporada atual.');
  state.team=team;state.slug=aliases[norm(team.name)]||slug(team.name);setCanonicalTeamRoute(team);renderShell(team);
  // Maps improve images in the background; their response time never blocks the profile.
  Promise.resolve(window.cffLoadPlayerPhotoMap?.()).then(refreshImages).catch(()=>{});
  Promise.resolve(window.cffLoadTeamLogoMap?.()).then(refreshImages).catch(()=>{});
  json(`team-data/profile-identity.json?v=${V}`).then(data=>{state.identity=data.teams?.[state.slug];applyIdentity()}).catch(()=>{});
  ensureHistoryData().then(data=>{renderTitles(data);renderResults(data)}).catch(()=>{document.getElementById('cff-team-titles-mount').innerHTML='<div class="cff-public-empty">Conquistas indisponíveis no momento.</div>';document.getElementById('cff-team-results-mount').innerHTML='<div class="cff-public-empty">Resultados indisponíveis no momento.</div>'});
  const [current,stats,stages]=await Promise.all([json(`player-data/s2/${state.slug}.json?v=${V}`),json(`ffws-br-2026-s2/player-stats.json?v=${V}`).catch(()=>({players:{}})),json(`ffws-br-2026-s2/career-summary.json?v=${V}`).catch(()=>({}))]);
  state.current=current;state.stats=stats;state.stages=stages;if(state.activeSeason==='s2'&&document.querySelector('[data-team-season="s2"]')?.getAttribute('aria-selected')==='true')renderS2();renderCurrentRoster();refreshImages();
  if(state.historyData&&document.getElementById('cff-team-history-section')?.dataset.loaded==='1')renderHistory(state.historyData);
  const requested=String(location.hash||'').match(/^#cff-profile-(summary|roster|results|titles|history)$/)?.[1];if(requested){await ensureHistoryData().catch(()=>null);jumpToProfileSection(requested);}
 }catch(error){fail(error.message)}
}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init,{once:true}):init();
})();
